SELECT id, customer_id, status, MIN(balance) OVER (PARTITION BY status ORDER BY balance, id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS last7_min_balance, SUM(balance) OVER (PARTITION BY status ORDER BY balance, id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS last7_sum_balance, COUNT(balance) OVER (PARTITION BY status ORDER BY balance, id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS last7_count_balance, PERCENT_RANK() OVER (PARTITION BY account_type, customer_id ORDER BY balance DESC NULLS FIRST) AS balance_percent_rank FROM accounts WHERE customer_id IS NOT NULL;
